/* Motorola 6809 emulator (C99, no 64-bit arithmetic, no FPU).
 *
 * Follows MAME 0.289 m6809 (base6x09.lst / m6809.lst): every memory access, opcode fetch
 * and dummy cycle costs one cycle, so instruction and interrupt timings match MAME.
 * Interrupts are checked between instructions (MAME can also stop inside one).
 *
 * The same state is used by the 68k assembler core (m6809_68k.s, generated by
 * tools/gen_6809_68k.py): the struct layout is fixed (32 bit fields first, then 16 and 8
 * bit ones, so no padding) and checked by m6809_layout_ok().
 */
#ifndef M6809_H
#define M6809_H

#include <stdint.h>

enum {
    M6809_CC_C = 0x01, M6809_CC_V = 0x02, M6809_CC_Z = 0x04, M6809_CC_N = 0x08,
    M6809_CC_I = 0x10, M6809_CC_H = 0x20, M6809_CC_F = 0x40, M6809_CC_E = 0x80
};

typedef struct M6809 M6809;

typedef uint8_t (*m6809_read_fn)(void *ctx, uint16_t addr);
typedef void (*m6809_write_fn)(void *ctx, uint16_t addr, uint8_t data);

struct M6809 {
    /* memory: direct pages (256 B) for reading opcodes/data and for writing; NULL = handler.
       Set with m6809_map_page(), which also keeps rbase/wbase (page pointer - page * 256:
       host address = base + guest address) for the assembler core. */
    const uint8_t *rpage[256];              /* 0 */
    uint8_t *wpage[256];                    /* 1024 */
    const uint8_t *rbase[256];              /* 2048 */
    uint8_t *wbase[256];                    /* 3072 */
    m6809_read_fn read;                     /* 4096 */
    m6809_write_fn write;                   /* 4100 */
    void *ctx;                              /* 4104 */
    void (*hook)(M6809 *cpu);               /* 4108: per-instruction hook for tests (C core) */

    /* cycles: run() executes until icount <= 0; total counts all executed cycles */
    int32_t icount;                         /* 4112 */
    uint32_t total;                         /* 4116 */

    /* idle loop skipping (exact): addresses of pure polling loops (reads, and writes that
       repeat the same effect). When the CPU comes back to such an address with the same
       registers and no interrupt pending, the remaining whole turns of the loop in this time
       slice are skipped: nothing outside the CPU changes during its slice. */
    const uint8_t *idle_sig[8];             /* 4120: the loop's code (checked: ROM banks) */
    int32_t idle_icount;                    /* 4152 */
    uint32_t idle_skipped;                  /* 4156: statistics: cycles skipped */

    /* 16 bit registers */
    uint16_t x, y, u, s, pc;                /* 4160 .. 4168 */
    uint16_t ppc;                           /* 4170: address of the current instruction */
    uint16_t idle_pc[8];                    /* 4172 */
    uint16_t idle_at;                       /* 4188 */

    /* 8 bit registers (dp at an even offset, followed by cc: the asm core reads them as a word) */
    uint8_t a, b, dp, cc;                   /* 4190 .. 4193 */
    uint8_t nmi_line, firq_line, irq_line;  /* 4194 .. 4196: interrupt lines (set by the machine) */
    uint8_t nmi_pending;                    /* 4197: NMI edge latched (only after the first LDS) */
    uint8_t lds_seen;                       /* 4198 */
    uint8_t waiting;                        /* 4199: 1 = CWAI (state pushed), 2 = SYNC */
    uint8_t freerun;                        /* 4200: undocumented test mode (14, 15, CD): stops */
    uint8_t idle_len[8];                    /* 4201 */
    uint8_t nidle;                          /* 4209 */
    uint8_t idle_valid;                     /* 4210 */
    uint8_t idle_regs[12];                  /* 4211 */
    uint8_t pad;                            /* 4223 */
    uint8_t idle_map[8192];                 /* 4224: bit per address: an idle loop starts here */

    /* 12416: one I/O address whose read the assembler core answers without calling the read
       handler: fast_val while fast_ok (kept up to date by the machine; the C core always calls
       the handler) */
    uint16_t fast_addr;                     /* 12416 */
    uint8_t fast_val, fast_ok;              /* 12418, 12419 */

    /* 12420: translated code (m6809_tr.c, assembler core only): host code of each instruction
       of 8000-FFFF (index PC - 8000), NULL = none; the whole pointer NULL = no translation */
    void **trmap;                           /* 12420 */

    /* addresses where an IRQ is not taken (held until PC leaves them; C core only, which also
       takes the interrupts for the assembler core): the machine's fix for a race of the game */
    uint16_t irq_hold[8];
    uint8_t nirq_hold;
};

#define M6809_OFS_IDLE_MAP 4224

void m6809_init(M6809 *cpu);
void m6809_reset(M6809 *cpu);
/* page p (0-255) of the address space: read and write pointers to 256 bytes, or NULL for the
   read / write handlers */
void m6809_map_page(M6809 *cpu, int p, const uint8_t *r, uint8_t *w);
/* runs at least `cycles` cycles (whole instructions); returns cycles executed */
int32_t m6809_run(M6809 *cpu, int32_t cycles);
/* executes one instruction or interrupt entry; returns its cycles */
int32_t m6809_step(M6809 *cpu);
void m6809_set_nmi(M6809 *cpu, int state);
/* registers a pure polling loop at addr whose code is sig[0..len-1] (see idle_pc) */
void m6809_add_idle_loop(M6809 *cpu, uint16_t addr, const uint8_t *sig, int len);
/* 1 if the struct layout is the one the assembler core expects */
int m6809_layout_ok(void);

/* the assembler core (68k): the same as m6809_run */
int32_t m6809_run_asm(M6809 *cpu, int32_t cycles);
/* Xain'd Sleena main CPU: runs the translated sprite list routine DCEC-DE88 while PC is in it and
   cycles are left (icount > 0); no interrupt may be pending (the caller checks). Exact. */
void m6809_run_spr(M6809 *cpu);
/* used by the assembler core */
uint32_t m6809_rd_slow(M6809 *cpu, uint32_t addr);
void m6809_wr_slow(M6809 *cpu, uint32_t addr, uint32_t data);
void m6809_idle_hit(M6809 *cpu);

/* translation (m6809_tr.c): the instructions of from..to (8000-FFFF, read through rpage) become
   68k code built from the templates of the assembler core; it runs the same handlers in the same
   order, without the dispatch (exact). 1 = done (cpu->trmap set); 0 = not possible (no assembler
   core, no memory). m6809_tr_free releases it. */
int m6809_tr_build(M6809 *cpu, uint16_t from, uint16_t to);
void m6809_tr_free(M6809 *cpu);
/* statistics of the last build: instructions translated, without a template, code bytes */
extern uint32_t m6809_tr_count, m6809_tr_missing, m6809_tr_bytes;
/* instructions per kind: specialized, branch, translation 1 template, C core step */
extern uint32_t m6809_tr_kinds[4];

#endif
